  "guide.pulse.pressureText": "ਤੁਹਾਡਾ ਵਿੱਤੀ ਦਬਾਅ ਸਕੋਰ (0-100) ਇਹ ਮਾਪਦਾ ਹੈ ਕਿ ਤੁਹਾਡੀ ਆਮਦਨ ਦਾ ਕਿੰਨਾ ਹਿੱਸਾ ਨਿਸ਼ਚਿਤ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨੂੰ ਜਾਂਦਾ ਹੈ। 45 ਤੋਂ ਹੇਠਾਂ ਸਿਹਤਮੰਦ ਹੈ। 70 ਤੋਂ ਉੱਪਰ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਤੁਹਾਡੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਭਾਰੀ ਹਨ।",
  "guide.pulse.freeCashTitle": "Free ਨਕਦ",
  "guide.pulse.freeCashText": "ਇਸ ਮਹੀਨੇ ਤੁਹਾਡੇ ਸਾਰੇ ਵਚਨਬੱਧ ਭੁਗਤਾਨਾਂ ਤੋਂ ਬਾਅਦ ਬਚਿਆ ਪੈਸਾ। ਇਹ ਉਹ ਹੈ ਜੋ ਤੁਹਾਨੂੰ ਅਸਲ ਵਿੱਚ ਖਰਚ ਕਰਨਾ, ਬਚਾਉਣ ਜਾਂ ਨਿਵੇਸ਼ ਕਰਨਾ ਹੈ।",
  "guide.pulse.survivalTitle": "ਸਰਵਾਈਵਲ ਰਨਵੇ",
  "guide.pulse.survivalText": "ਜੇਕਰ ਤੁਸੀਂ ਅੱਜ ਸਾਰੀ ਆਮਦਨ ਗੁਆ ​​ਦਿੱਤੀ ਹੈ, ਤਾਂ ਤੁਸੀਂ ਬਚਤ ਤੋਂ ਕਿੰਨੇ ਮਹੀਨਿਆਂ ਲਈ ਆਪਣੀਆਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨੂੰ ਪੂਰਾ ਕਰ ਸਕਦੇ ਹੋ? 6+ ਮਹੀਨੇ ਦਾ ਟੀਚਾ ਹੈ।",
  "support.title": "ਮਦਦ ਅਤੇ ਸਹਾਇਤਾ",
  "support.subtitle": "ਮਾਰਗਦਰਸ਼ਨ, ਗੋਪਨੀਯਤਾ, ਅਤੇ ਸਾਡੇ ਤੱਕ ਪਹੁੰਚਣ ਦੇ ਤਰੀਕੇ।",
  "support.helpCenter": "ਐਪ ਗਾਈਡ ਖੋਲ੍ਹੋ",
  "support.helpCenterHint": "ਘਰ, ਨਬਜ਼, ਅਤੇ ਬਿੱਲ ਐਂਟਰੀ ਦੇ ਵਾਕਥਰੂ ਨੂੰ ਦੁਬਾਰਾ ਚਲਾਓ।",
  "support.privacy": "ਪਰਾਈਵੇਟ ਨੀਤੀ",
  "support.privacyHint": "ਅਸੀਂ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਤੁਹਾਡੇ ਡੇਟਾ ਨੂੰ ਕਿਵੇਂ ਸੰਭਾਲਦੇ ਹਾਂ।",
  "support.contact": "ਸਹਾਇਤਾ ਨਾਲ ਸੰਪਰਕ ਕਰੋ",
  "support.contactHint": "ਖਾਤੇ ਜਾਂ ਉਤਪਾਦ ਦੇ ਸਵਾਲਾਂ ਲਈ ਈਮੇਲ Perovo.",
  "support.contactEmail": "support@tadsaya.com",
  "support.about": "ਬਾਰੇ Perovo",
  "support.aboutBody": "Perovo ਭਾਰਤੀ ਪਰਿਵਾਰਾਂ ਨੂੰ ਬਿੱਲਾਂ, ਉਧਾਰ ਦੇਣ ਅਤੇ ਮਹੀਨਾਵਾਰ ਦਬਾਅ ਨੂੰ ਟਰੈਕ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। Perovo ਦੁਆਰਾ ਬਣਾਇਆ ਗਿਆ, Perovo ਦੇ ਅਧੀਨ ਇੱਕ SaaS ਕੰਪਨੀ।",
  "support.version": "ਸੰਸਕਰਣ {version}",
