  "notifications.remindersHint": "ਬਿੱਲਾਂ ਦੇ ਬਕਾਇਆ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਸੂਚਨਾ ਪ੍ਰਾਪਤ ਕਰੋ",
  "notifications.overdueAlerts": "Overdue alerts",
