  "notifications.weeklyDigest": "Weekly digest",
  "notifications.weeklyDigestHint": "ਤੁਹਾਡੀ ਵਿੱਤੀ ਸਥਿਤੀ ਦਾ ਐਤਵਾਰ ਦਾ ਸਾਰ",
  "notifications.permission": "ਬ੍ਰਾਊਜ਼ਰ ਦੀ ਇਜਾਜ਼ਤ",
  "notifications.enableAlerts": "ਬ੍ਰਾਊਜ਼ਰ ਚੇਤਾਵਨੀਆਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਓ",
  "notifications.sendTest": "ਟੈਸਟ ਭੇਜੋ",
  "notifications.markRead": "ਸਾਰੀਆਂ ਸੂਚਨਾਵਾਂ ਨੂੰ ਪੜ੍ਹੇ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰੋ",
  "notifications.unsupported": "ਤੁਹਾਡਾ ਬ੍ਰਾਊਜ਼ਰ ਸੂਚਨਾਵਾਂ ਦਾ ਸਮਰਥਨ ਨਹੀਂ ਕਰਦਾ ਹੈ।",
  "notifications.enabledOk": "ਬ੍ਰਾਊਜ਼ਰ ਸੁਚੇਤਨਾਵਾਂ ਨੂੰ ਚਾਲੂ ਕੀਤਾ ਗਿਆ। ਐਪ ਬੰਦ ਹੋਣ 'ਤੇ ਅਲਰਟ ਲਈ ਹੋਮ ਸਕ੍ਰੀਨ 'ਤੇ ਐਪ ਸ਼ਾਮਲ ਕਰੋ।",
  "notifications.enableAlertsNative": "ਸੂਚਨਾਵਾਂ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ",
  "notifications.enabledOkNative": "ਸੂਚਨਾਵਾਂ ਚਾਲੂ ਕੀਤੀਆਂ ਗਈਆਂ। ਬਕਾਇਆ ਅਤੇ ਬਕਾਇਆ ਬਿੱਲ ਤੁਹਾਨੂੰ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਸੁਚੇਤ ਕਰਨਗੇ।",
  "notifications.deniedErrNative": "Android ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਬਲੌਕ ਕੀਤਾ ਗਿਆ। ਸੈਟਿੰਗਾਂ → ਐਪਾਂ → ਪੇਰੋਵੋ → ਸੂਚਨਾਵਾਂ ਖੋਲ੍ਹੋ ਅਤੇ ਚੇਤਾਵਨੀਆਂ ਦੀ ਆਗਿਆ ਦਿਓ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "notifications.testDeniedNative": "ਆਗਿਆ ਤੋਂ ਇਨਕਾਰ. Android ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਸੂਚਨਾਵਾਂ ਦੀ ਆਗਿਆ ਦਿਓ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "notifications.nativeHint": "ਟਰੇ ਚੇਤਾਵਨੀਆਂ Android ਸੂਚਨਾਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦੀਆਂ ਹਨ। ਇਸ ਸਕ੍ਰੀਨ ਵਿੱਚ ਬਿੱਲ ਰੀਮਾਈਂਡਰ ਚਾਲੂ ਰੱਖੋ। ਐਪ ਬੰਦ ਹੋਣ 'ਤੇ ਵੀ ਬਕਾਇਆ ਅਤੇ ਬਕਾਇਆ ਬਿੱਲਾਂ ਨੂੰ ਸੂਚਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "notifications.deniedErr": "ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਬਲੌਕ ਕੀਤਾ ਗਿਆ। ਇਸ ਸਾਈਟ ਲਈ ਸੂਚਨਾਵਾਂ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "notifications.testOk": "ਤੁਹਾਡੇ ਸਿਸਟਮ ਸੂਚਨਾ ਪੈਨਲ ਅਤੇ ਇਨ-ਐਪ ਘੰਟੀ ਨੂੰ ਭੇਜਿਆ ਗਿਆ। ਇਸਨੂੰ ਦੇਖਣ ਲਈ ਫ਼ੋਨ 'ਤੇ ਹੇਠਾਂ ਵੱਲ ਸਵਾਈਪ ਕਰੋ।",
  "notifications.testDenied": "ਆਗਿਆ ਤੋਂ ਇਨਕਾਰ. ਬ੍ਰਾਊਜ਼ਰ ਜਾਂ OS ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਚੇਤਾਵਨੀਆਂ ਨੂੰ ਚਾਲੂ ਕਰੋ।",
  "notifications.testUnsupported": "ਇਹ ਬ੍ਰਾਊਜ਼ਰ ਸੂਚਨਾਵਾਂ ਦਾ ਸਮਰਥਨ ਨਹੀਂ ਕਰਦਾ ਹੈ।",
  "notifications.testFail": "ਚੇਤਾਵਨੀ ਨਹੀਂ ਦਿਖਾਈ ਜਾ ਸਕੀ। ਐਪ ਨੂੰ ਸਥਾਪਿਤ ਕਰੋ (ਹੋਮ ਸਕ੍ਰੀਨ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰੋ) ਜਾਂ Chrome/Edge ਦੀ ਵਰਤੋਂ ਕਰੋ।",
  "notifications.testInApp": "ਜਾਂਚ ਰੀਮਾਈਂਡਰ — ਸੂਚਨਾਵਾਂ ਇਸ ਡਿਵਾਈਸ 'ਤੇ ਕੰਮ ਕਰ ਰਹੀਆਂ ਹਨ।",
  "notifications.installHint": "ਟਰੇ ਚੇਤਾਵਨੀਆਂ ਲਈ: ਐਪ ਨੂੰ ਸਥਾਪਿਤ ਕਰੋ (ਹੋਮ ਸਕ੍ਰੀਨ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰੋ), ਸੂਚਨਾਵਾਂ ਦੀ ਆਗਿਆ ਦਿਓ, ਅਤੇ ਰੀਮਾਈਂਡਰ ਚਾਲੂ ਰੱਖੋ। ਜਦੋਂ ਤੁਸੀਂ ਐਪ ਛੱਡਦੇ ਹੋ ਜਾਂ ਹਰ ਕੁਝ ਘੰਟਿਆਂ (Android/Chrome) ਨੂੰ ਛੱਡਦੇ ਹੋ ਤਾਂ ਬਕਾਇਆ ਅਤੇ ਬਕਾਇਆ ਬਿੱਲਾਂ ਨੂੰ ਸੂਚਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। iPhone ਨੂੰ ਹੋਮ-ਸਕ੍ਰੀਨ ਐਪ ਆਈਕਨ ਦੀ ਲੋੜ ਹੈ — Safari ਟੈਬਾਂ ਹੀ ਬੈਕਗ੍ਰਾਊਂਡ-ਸੂਚਨਾ ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ।",
  "notifications.pressureJump.title": "Perovo - ਦਬਾਅ ਤਬਦੀਲੀ",
