  "add.guidanceRollForward": "ਤੁਹਾਡੇ ਦੁਆਰਾ ਇੱਕ ਚੱਕਰ ਨੂੰ ਸਾਫ਼ ਕਰਨ ਤੋਂ ਬਾਅਦ ਮਹੀਨਾਵਾਰ ਅਤੇ ਸਾਲਾਨਾ ਆਈਟਮਾਂ ਅੱਗੇ ਵਧਦੀਆਂ ਹਨ",
