  "add.form.chitInstallmentHint": "ਚਿਤ ਮੁੱਲ ਅਤੇ ਮਹੀਨੇ ਤੋਂ। ਜੇਕਰ ਤੁਹਾਡਾ ਸਮੂਹ ਕਿਸੇ ਵੱਖਰੇ ਨੰਬਰ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ ਤਾਂ ਚਿੱਟ ਵੇਰਵਿਆਂ ਵਿੱਚ \"ਨਿਸ਼ਚਿਤ ਰਕਮ\" ਦੀ ਵਰਤੋਂ ਕਰੋ।",
  "add.form.chitRepeatNote": "ਚਿੱਟ ਖਤਮ ਹੋਣ ਤੱਕ ਮਹੀਨਾਵਾਰ ਦੁਹਰਾਇਆ ਜਾਂਦਾ ਹੈ। ਜਦੋਂ ਇੱਕ ਨਵਾਂ ਮਹੀਨਾ ਸ਼ੁਰੂ ਹੁੰਦਾ ਹੈ, ਤਾਂ ਤੁਹਾਡੀ ਬਕਾਇਆ ਰਕਮ ਹੇਠਲੀ ਕਿਸ਼ਤ ਵਿੱਚ ਅੱਪਡੇਟ ਹੋ ਜਾਂਦੀ ਹੈ — ਤੁਸੀਂ ਇਸਨੂੰ ਖੁਦ ਨਹੀਂ ਬਦਲਦੇ।",
