  "add.form.priorityAuto": "{category} ਬਿੱਲਾਂ ਲਈ ਤਰਜੀਹ ਸਵੈਚਲਿਤ ਤੌਰ 'ਤੇ ਸੈੱਟ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
