  "sync.noRemoteBackup": "ਹਾਲੇ ਤੱਕ ਕੋਈ ਕਲਾਊਡ ਬੈਕਅੱਪ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਕੀਤਾ ਗਿਆ। ਬੈਕਅੱਪ ਚਾਲੂ ਕਰੋ ਅਤੇ ਪਹਿਲਾਂ ਬੈਕਅੱਪ ਹੁਣੇ 'ਤੇ ਟੈਪ ਕਰੋ।",
