  "insight.burden-danger": "EMI-ਸ਼ੈਲੀ ਦਾ ਬੋਝ ਆਮਦਨ ਦੇ ਮੁਕਾਬਲੇ ਉੱਚ ਸੀਮਾ ਵਿੱਚ ਹੈ। ਜੇ ਸੰਭਵ ਹੋਵੇ ਤਾਂ ਨਵੀਆਂ ਵਚਨਬੱਧਤਾਵਾਂ ਨੂੰ ਮੁਲਤਵੀ ਕਰੋ।",
