  "insight.subs-weight": "ਗਾਹਕੀਆਂ ਤੁਹਾਡੀ ਬੇਸਲਾਈਨ ਵਿੱਚ ਲਗਭਗ {amount}/mo ਜੋੜਦੀਆਂ ਹਨ — ਸਮੇਂ ਦੇ ਨਾਲ ਆਵਰਤੀ ਲਾਗਤਾਂ ਇਕੱਠੀਆਂ ਹੁੰਦੀਆਂ ਹਨ।",
  "insight.open-up": "ਪੁਰਾਣੇ ਸਨੈਪਸ਼ਾਟ ({fromMonth} → {toMonth}) ਦੇ ਮੁਕਾਬਲੇ ਖੁੱਲ੍ਹੇ ਬਿੱਲ ਦਾ ਬਕਾਇਆ ਵਧਿਆ ਹੈ।",
  "insight.pressure-down": "ਤੁਸੀਂ ਪਿਛਲੇ ਮਹੀਨੇ ਦੇ ਸਨੈਪਸ਼ਾਟ ਦੇ ਮੁਕਾਬਲੇ ਓਪਨ ਬਿਲ ਦਾ ਦਬਾਅ ਘਟਾਇਆ ਹੈ।",
  "insight.multi-overdue": "{count} ਆਈਟਮਾਂ ਬਕਾਇਆ ਹਨ — ਉਹਨਾਂ ਨੂੰ ਪਹਿਲਾਂ ਸਾਫ਼ ਕਰਨ ਨਾਲ ਆਮ ਤੌਰ 'ਤੇ ਸਿੱਧੇ ਤੌਰ 'ਤੇ ਦਬਾਅ ਘੱਟ ਜਾਂਦਾ ਹੈ।",
  "insight.paying-habit": "ਤੁਸੀਂ ਇਸ ਮਹੀਨੇ ਭੁਗਤਾਨਾਂ ਵਿੱਚ {amount} ਦਰਜ ਕੀਤਾ ਹੈ — ਲਗਾਤਾਰ ਭੁਗਤਾਨ ਵਿੱਤੀ ਰਨਵੇ ਵਿੱਚ ਸੁਧਾਰ ਕਰਦੇ ਹਨ।",
  "insight.overlap-week": "ਤੁਹਾਡੇ ਕੋਲ ਇਸ ਹਫ਼ਤੇ {count} ਬਕਾਏ ਹਨ (≈{total} ਕੁੱਲ)—ਜੇ ਸੰਭਵ ਹੋਵੇ ਤਾਂ ਹੈਰਾਨ ਕਰਨ ਵਾਲੇ ਭੁਗਤਾਨ।",
  "insight.forecast-crunch-negative": "ਤੁਹਾਨੂੰ {month} ਦੇ ਆਸਪਾਸ ਨਕਾਰਾਤਮਕ ਮੁਫਤ ਨਕਦੀ ਦਾ ਸਾਹਮਣਾ ਕਰਨਾ ਪੈ ਸਕਦਾ ਹੈ (ਉਸ ਮਹੀਨੇ ਦੀ ਆਮਦਨ ਤੋਂ ਵੱਧ ਬਕਾਇਆ)।",
  "insight.forecast-crunch-tight": "ਨਕਦ {month} ਦੇ ਆਸਪਾਸ ਸੀਮਤ ਹੋ ਸਕਦਾ ਹੈ — ਅਨੁਮਾਨਿਤ ਬਕਾਇਆ ਤੋਂ ਬਾਅਦ ਸਿਰਫ਼ ≈{free} ਮੁਫ਼ਤ।",
  "insight.subs-yearly": "ਤੁਹਾਡੀਆਂ ਗਾਹਕੀਆਂ ਦੀ ਕੀਮਤ ਮੌਜੂਦਾ ਦਰਾਂ 'ਤੇ ਲਗਭਗ {amount}/ਸਾਲ ਹੋ ਸਕਦੀ ਹੈ।",
  "insight.emi-pct": "EMI ਤੁਹਾਡੀ ਦੱਸੀ ਗਈ ਮਹੀਨਾਵਾਰ ਆਮਦਨ ਦਾ ਲਗਭਗ {percent}% ਵਰਤਦੇ ਹਨ — ਨਵੇਂ ਉਧਾਰ ਲੈਣ ਨਾਲ ਸਾਵਧਾਨੀ ਵਰਤੋ।",
  "insight.txn-delivery-dependency": "ਭੋਜਨ ਡਿਲਿਵਰੀ ਖਰਚ ਇਸ ਹਫਤੇ ਇੱਕ ਵੱਡਾ ਹਿੱਸਾ ਹੈ — ਨਿਰਭਰਤਾ ਚੁੱਪ-ਚਾਪ ਵਧ ਸਕਦੀ ਹੈ।",
  "insight.txn-health-spend-week": "ਸਿਹਤ-ਸਬੰਧਤ ਖਰਚੇ ਇਸ ਹਫਤੇ ਵਧੇ ਹਨ - ਬਚਾਅ ਦੇ ਖਰਚੇ ਥੋੜ੍ਹੇ ਸਮੇਂ ਦੇ ਨਕਦ ਨੂੰ ਤੰਗ ਕਰ ਸਕਦੇ ਹਨ।",
  "insight.txn-discretionary-rise": "ਰੋਜ਼ਾਨਾ ਅਖਤਿਆਰੀ ਖਰਚ ਪਿਛਲੇ ਮਹੀਨੇ ਦੇ ਮੁਕਾਬਲੇ ਵਧਿਆ ਹੈ।",
  "insight.txn-lifestyle-stack": "ਆਵਰਤੀ {merchant} ਲਾਗਤਾਂ ਦਾ ਸਟੈਕ ਹਾਲੀਆ ਜੀਵਨ ਸ਼ੈਲੀ ਦੇ ਖਰਚਿਆਂ ਨਾਲ — ਸਮੀਖਿਆ ਓਵਰਲੈਪ।",
  "insight.txn-small-leaks": "ਇਸ ਹਫ਼ਤੇ ਕਈ ਛੋਟੀਆਂ ਖਰੀਦਾਂ ਹੌਲੀ ਹੌਲੀ ਮਹੀਨਾਵਾਰ ਲਚਕਤਾ ਨੂੰ ਘਟਾ ਰਹੀਆਂ ਹਨ।",
  "insight.txn-recurring-merchants": "{count} ਵਪਾਰੀ ਤੁਹਾਡੇ ਲੌਗ ਕੀਤੇ ਖਰਚਿਆਂ ਤੋਂ ਆਵਰਤੀ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ — ਸਮੀਖਿਆ ਕਰੋ ਕਿ ਕੀ ਕੋਈ ਬਿੱਲ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "insight.txn-daily-budget-cap": "ਬਿੱਲ ਆਮਦਨ ਦਾ ~{percent}% ਵਰਤਦੇ ਹਨ — ਬਾਕੀ ਮਹੀਨੇ ਲਈ ਜੀਵਨਸ਼ੈਲੀ ਖਰਚਿਆਂ 'ਤੇ ਲਗਭਗ {cap}/ਦਿਨ ਦਾ ਟੀਚਾ ਹੈ।",
  "insight.txn-daily-budget-room": "ਬਕਾਇਆ ਦੇ ਬਾਅਦ, ਇਸ ਮਹੀਨੇ ਦੇ ਬਾਕੀ ਹਿੱਸੇ ਲਈ ਲਗਭਗ {amount}/ਦਿਨ ਲਚਕਦਾਰ ਰਹਿੰਦਾ ਹੈ।",
  "insight.txn-recurring-growth-high": "ਆਵਰਤੀ ਵਿਕਲਪਿਕ ਖਰਚ ਹੌਲੀ-ਹੌਲੀ ਵੱਧ ਰਹੇ ਹਨ — ਛੋਟੇ ਦੁਹਰਾਓ ਲਚਕਤਾ ਨੂੰ ਘਟਾ ਸਕਦੇ ਹਨ।",
  "insight.txn-recurring-growth": "ਆਵਰਤੀ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਹਾਲ ਦੇ ਮਹੀਨਿਆਂ ਵਿੱਚ ਲਗਭਗ {percent}% ਵਧੀਆਂ ਹਨ।",
  "insight.txn-under-pressure": "ਅਖਤਿਆਰੀ ਰੋਜ਼ਾਨਾ ਖਰਚ ਜਾਰੀ ਰਹਿੰਦਾ ਹੈ ਜਦੋਂ ਕਿ ਜ਼ਿੰਮੇਵਾਰੀ ਦਾ ਦਬਾਅ ਪਹਿਲਾਂ ਹੀ ਉੱਚਾ ਹੁੰਦਾ ਹੈ।",
  "insight.txn-rhythm-unsafe": "ਇੱਕ ਆਗਾਮੀ ਹਫ਼ਤੇ ਵਿੱਚ ਸੰਘਣੀ ਨਿਯਤ ਮਿਤੀਆਂ ਹਨ - ਇਸਨੂੰ ਇੱਕ ਉੱਚ-ਜੋਖਮ ਵਾਲੀ ਨਕਦ ਵਿੰਡੋ ਵਜੋਂ ਮੰਨੋ।",
  "insight.txn-rhythm-overlap": "ਅਗਲੇ ਹਫ਼ਤੇ ਵਿੱਚ ਕਈ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਓਵਰਲੈਪ ਹੋ ਜਾਂਦੀਆਂ ਹਨ — ਸਟੈਕ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਨਕਦੀ ਦੀ ਯੋਜਨਾ ਬਣਾਓ।",
  "insight.txn-rhythm-lifestyle": "ਹਾਲੀਆ ਰੋਜ਼ਾਨਾ ਖਰਚ ਪਤਲੀ ਜੀਵਨਸ਼ੈਲੀ-ਭਾਰੀ — ਅਖਤਿਆਰੀ ਪ੍ਰਵਾਹ ਲਚਕਤਾ ਨੂੰ ਘਟਾ ਰਿਹਾ ਹੋ ਸਕਦਾ ਹੈ।",
  "insight.feed-restaurant-week": "ਰੈਸਟੋਰੈਂਟ ਅਤੇ ਡਿਲੀਵਰੀ ਖਰਚੇ ਇਸ ਹਫਤੇ ਵਧੇ ਹਨ।",
  "insight.feed-medical-month": "ਡਾਕਟਰੀ ਖਰਚੇ ਇਸ ਮਹੀਨੇ ਆਮ ਨਾਲੋਂ ਵੱਧ ਹਨ।",
