  "profileHub.scorePayOrder": "ਸੁਝਾਏ ਗਏ ਪੇ ਆਰਡਰ",
  "profileHub.scorePayOrderHint": "ਨਕਦੀ ਤੰਗ ਹੋਣ 'ਤੇ ਪਹਿਲਾਂ ਬਕਾਇਆ ਅਤੇ ਉੱਚ-ਵਿਆਜ ਵਾਲੇ ਬਿੱਲਾਂ ਦਾ ਭੁਗਤਾਨ ਕਰੋ।",
