  "profileHub.scoreFix.payFirst": "ਪਹਿਲਾਂ ਇਸ ਦਾ ਭੁਗਤਾਨ ਕਰੋ",
  "profileHub.scoreFix.payFirstHint": "ਬਕਾਇਆ / ਉੱਚ-ਵਿਆਜ ਵਾਲਾ ਭਾਰ ਸਭ ਤੋਂ ਤੇਜ਼ੀ ਨਾਲ ਸਾਫ਼ ਕਰਦਾ ਹੈ।",
  "profileHub.scoreWhy.pressure.what": "ਇਹ ਮਾਪਦਾ ਹੈ ਕਿ ਤੁਹਾਡੀ ਆਮਦਨ ਦਾ ਕਿੰਨਾ ਹਿੱਸਾ ਬਿੱਲਾਂ ਅਤੇ ਬਕਾਇਆ ਵਸਤੂਆਂ ਵਿੱਚ ਬੰਦ ਹੈ।",
  "profileHub.scoreWhy.pressure.high": "ਬਹੁਤ ਸਾਰੇ ਬਿੱਲ ਆਮਦਨ ਦੇ ਅਨੁਸਾਰ ਜਲਦੀ ਜਾਂ ਬਕਾਇਆ ਹਨ।",
  "profileHub.scoreWhy.pressure.mid": "ਆਮਦਨ ਦਾ ਇੱਕ ਧਿਆਨ ਦੇਣ ਯੋਗ ਹਿੱਸਾ ਆਵਰਤੀ ਬਕਾਏ ਵਿੱਚ ਜਾਂਦਾ ਹੈ।",
  "profileHub.scoreWhy.pressure.low": "ਬਿਲ ਇਸ ਸਮੇਂ ਆਮਦਨ ਦੇ ਅਨੁਸਾਰ ਪ੍ਰਬੰਧਨਯੋਗ ਹਨ।",
  "profileHub.scoreWhy.health.what": "ਬਿੱਲ ਦੇ ਬੋਝ, ਭੁਗਤਾਨ ਦੀਆਂ ਆਦਤਾਂ, ਬਚਤ ਬਫਰ, ਅਤੇ ਕਰਜ਼ੇ ਦੇ ਰੁਝਾਨ ਨੂੰ ਜੋੜਦਾ ਹੈ।",
  "profileHub.scoreWhy.health.low": "ਬੋਝ, ਬਫਰ, ਜਾਂ ਭੁਗਤਾਨ ਦੀ ਇਕਸਾਰਤਾ ਵਿੱਚ ਕਮਜ਼ੋਰੀ ਇਸ ਨੂੰ ਹੇਠਾਂ ਖਿੱਚ ਰਹੀ ਹੈ।",
  "profileHub.scoreWhy.health.mid": "ਕੁਝ ਖੇਤਰਾਂ ਵਿੱਚ ਠੋਸ — ਕੁਝ ਆਦਤਾਂ ਜਾਂ ਬਫਰ ਇਸ ਨੂੰ ਚੁੱਕ ਸਕਦੇ ਹਨ।",
  "profileHub.scoreWhy.health.good": "ਸਮੁੱਚੀ ਆਦਤਾਂ ਅਤੇ ਬਫਰ ਸਿਹਤਮੰਦ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ।",
  "profileHub.scoreWhy.runway.what": "ਜੇਕਰ ਆਮਦਨੀ ਰੁਕ ਜਾਂਦੀ ਹੈ (ਤਰਲ ਬਚਤ + ਮੁਫਤ ਨਕਦ) ਤਾਂ ਮਹੀਨੇ ਤੁਸੀਂ ਜ਼ਰੂਰੀ ਚੀਜ਼ਾਂ ਨੂੰ ਕਵਰ ਕਰ ਸਕਦੇ ਹੋ।",
  "profileHub.scoreWhy.runway.critical": "ਬਹੁਤ ਪਤਲੀ ਗੱਦੀ - ਇੱਕ ਆਮਦਨੀ ਦੇ ਝਟਕੇ ਨੂੰ ਜਜ਼ਬ ਕਰਨਾ ਔਖਾ ਹੋਵੇਗਾ।",
  "profileHub.scoreWhy.runway.thin": "ਇੱਕ ਆਰਾਮਦਾਇਕ 3-6 ਮਹੀਨੇ ਦੇ ਰਿਜ਼ਰਵ ਦੇ ਹੇਠਾਂ।",
  "profileHub.scoreWhy.runway.ok": "ਰਨਵੇਅ ਫਿਲਹਾਲ ਸੁਰੱਖਿਅਤ ਦਾਇਰੇ ਵਿੱਚ ਹੈ।",
  "profileHub.scoreWhy.flexibility.what": "ਨਿਸ਼ਚਿਤ ਮਾਸਿਕ ਬਕਾਏ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ ਕੋਲ ਕਿੰਨੀ ਜਗ੍ਹਾ ਹੈ।",
  "profileHub.scoreWhy.flexibility.low": "ਜ਼ਿਆਦਾਤਰ ਆਮਦਨ ਪਹਿਲਾਂ ਹੀ ਆਵਰਤੀ ਬਿੱਲਾਂ ਲਈ ਵਚਨਬੱਧ ਹੈ।",
  "profileHub.scoreWhy.flexibility.ok": "ਤੁਸੀਂ ਹਰ ਮਹੀਨੇ ਅਰਥਪੂਰਨ ਮੁਫ਼ਤ ਨਕਦੀ ਬਰਕਰਾਰ ਰੱਖਦੇ ਹੋ।",
  "profileHub.scoreWhy.debt.what": "EMI ਅਤੇ ਮਹੀਨਾਵਾਰ ਆਮਦਨ ਦੇ ਹਿੱਸੇ ਵਜੋਂ ਕਰਜ਼ੇ ਦੀ ਅਦਾਇਗੀ।",
  "profileHub.scoreWhy.debt.high": "EMI ਲੋਡ ਭਾਰੀ ਹੈ — ਨਵੇਂ ਕਰਜ਼ੇ ਨਕਦੀ ਦੇ ਪ੍ਰਵਾਹ ਨੂੰ ਦਬਾਉਣਗੇ।",
  "profileHub.scoreWhy.debt.ok": "ਕਰਜ਼ੇ ਦੀ ਅਦਾਇਗੀ ਪ੍ਰਬੰਧਨਯੋਗ ਬੈਂਡ ਦੇ ਅੰਦਰ ਹੁੰਦੀ ਹੈ।",
  "profileHub.scoreWhy.lending.what": "ਤੁਹਾਡੇ ਦੁਆਰਾ ਉਧਾਰ ਵਿੱਚ ਦਿੱਤੇ ਜਾਂ ਪ੍ਰਾਪਤ ਕੀਤੇ ਸਮੇਂ 'ਤੇ ਅਦਾਇਗੀਆਂ ਨੂੰ ਟਰੈਕ ਕਰਦਾ ਹੈ।",
  "profileHub.scoreWhy.lending.empty": "ਅਜੇ ਤੱਕ ਕੋਈ ਉਧਾਰ ਇੰਦਰਾਜ਼ ਨਹੀਂ ਹਨ - ਇਸ ਸਕੋਰ ਨੂੰ ਬਣਾਉਣ ਲਈ ਸੌਦੇ ਅਤੇ ਲੌਗ ਭੁਗਤਾਨ ਸ਼ਾਮਲ ਕਰੋ।",
  "profileHub.scoreWhy.lending.low": "ਦੇਰ ਨਾਲ ਜਾਂ ਅੰਸ਼ਕ ਅਦਾਇਗੀਆਂ ਨੇ ਭਰੋਸਾ ਘਟਾਇਆ ਹੈ।",
  "profileHub.scoreWhy.lending.ok": "ਮੁੜ-ਭੁਗਤਾਨ ਇਤਿਹਾਸ ਭਰੋਸੇਯੋਗ ਲੱਗਦਾ ਹੈ।",
  "profileHub.scoreFix.pressure.clearOverdue": "ਪਹਿਲਾਂ ਬਕਾਇਆ ਬਿੱਲਾਂ ਨੂੰ ਸਾਫ਼ ਕਰੋ — ਉਹ ਇਸ ਸਕੋਰ ਨੂੰ ਸਭ ਤੋਂ ਵੱਧ ਨੁਕਸਾਨ ਪਹੁੰਚਾਉਂਦੇ ਹਨ।",
  "profileHub.scoreFix.pressure.trimSubscriptions": "ਗਾਹਕੀਆਂ ਅਤੇ ਵਿਕਲਪਿਕ EMIs ਦੀ ਸਮੀਖਿਆ ਕਰੋ ਜੋ ਤੁਸੀਂ ਰੋਕ ਸਕਦੇ ਹੋ।",
  "profileHub.scoreFix.pressure.payOnTime": "ਦਬਾਅ ਨੂੰ ਸਥਿਰ ਕਰਨ ਲਈ ਇਸ ਮਹੀਨੇ ਨਿਯਤ ਮਿਤੀਆਂ ਤੋਂ ਪਹਿਲਾਂ ਭੁਗਤਾਨ ਕਰੋ।",
  "profileHub.scoreFix.runway.buildReserve": "ਹਰ ਤਨਖ਼ਾਹ ਵਾਲੇ ਦਿਨ ਇੱਕ ਨਿਸ਼ਚਿਤ ਰਕਮ ਨੂੰ ਤਰਲ ਬਚਤ ਵਿੱਚ ਭੇਜੋ।",
  "profileHub.scoreFix.runway.reduceBurn": "ਰਨਵੇ ਨੂੰ ਵਧਾਉਣ ਲਈ ਗੈਰ-ਜ਼ਰੂਰੀ ਆਵਰਤੀ ਬਿੱਲਾਂ ਨੂੰ ਕੱਟੋ।",
  "profileHub.scoreFix.health.reduceBurden": "ਉੱਚ-ਬੋਝ ਪ੍ਰਤੀਬੱਧਤਾਵਾਂ ਨੂੰ ਘਟਾਓ ਜਾਂ ਮੁੜ ਤਹਿ ਕਰੋ।",
  "profileHub.scoreFix.health.buildBuffer": "ਤਰਲ ਬਚਤ ਵਿੱਚ 3-6 ਮਹੀਨਿਆਂ ਦੇ ਖਰਚਿਆਂ ਨੂੰ ਨਿਸ਼ਾਨਾ ਬਣਾਓ।",
  "profileHub.scoreFix.health.payOnTime": "ਇੱਕ ਭੁਗਤਾਨ ਸਟ੍ਰੀਕ ਰੱਖੋ — ਹਰ ਬਿਲ ਭੁਗਤਾਨ ਨੂੰ ਲੌਗ ਕਰੋ।",
  "profileHub.scoreFix.health.reduceDebt": "ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਸਭ ਤੋਂ ਵੱਧ ਵਿਆਜ ਬੈਲੰਸ 'ਤੇ ਚਿੱਪ ਦੂਰ ਕਰੋ।",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "ਆਮਦਨੀ, ਬਿੱਲਾਂ ਅਤੇ ਬੱਚਤਾਂ ਨੂੰ ਲੌਗ ਕਰੋ ਤਾਂ ਜੋ ਸਕੋਰ ਸਹੀ ਰਹੇ।",
  "profileHub.scoreFix.flexibility.reduceBurden": "ਘੱਟ ਆਵਰਤੀ ਬਕਾਏ ਜਾਂ ਗੱਲਬਾਤ ਕਰੋ EMI ਜਿੱਥੇ ਸੰਭਵ ਹੋਵੇ।",
  "profileHub.scoreFix.flexibility.trackSpend": "ਲੌਗ ਵੇਰੀਏਬਲ ਖਰਚ ਕਰੋ ਤਾਂ ਜੋ ਮੁਫਤ ਨਕਦ ਅਸਲੀਅਤ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੋਵੇ।",
  "profileHub.scoreFix.debt.attackHighInterest": "ਤਨਖਾਹ ਕ੍ਰਮ ਵਿੱਚ ਕ੍ਰੈਡਿਟ ਕਾਰਡ ਅਤੇ ਉੱਚ-ਦਰ ਦੇ ਕਰਜ਼ਿਆਂ ਨੂੰ ਤਰਜੀਹ ਦਿਓ।",
  "profileHub.scoreFix.debt.avoidNewEmi": "ਨਵੇਂ EMIs ਤੋਂ ਬਚੋ ਜਦੋਂ ਤੱਕ ਓਵਰਲੋਡ ਆਮਦਨ ਦੇ ~35% ਤੋਂ ਹੇਠਾਂ ਨਹੀਂ ਆ ਜਾਂਦਾ।",
  "profileHub.scoreFix.lending.onTime": "ਸਹਿਮਤੀ ਵਾਲੀ ਮਿਤੀ 'ਤੇ ਉਧਾਰ ਦੀਆਂ ਕਿਸ਼ਤਾਂ ਇਕੱਠੀਆਂ ਕਰੋ ਜਾਂ ਅਦਾ ਕਰੋ।",
  "profileHub.scoreFix.lending.addDeals": "ਟ੍ਰਸਟ ਨੂੰ ਟਰੈਕ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਉਧਾਰ ਪੰਨੇ ਤੋਂ ਇੱਕ ਉਧਾਰ ਇੰਦਰਾਜ਼ ਸ਼ਾਮਲ ਕਰੋ।",
  "profileHub.scoreFix.lending.document": "ਅੰਸ਼ਕ ਭੁਗਤਾਨਾਂ ਨੂੰ ਰਿਕਾਰਡ ਕਰੋ ਤਾਂ ਜੋ ਭਰੋਸਾ ਅਸਲੀਅਤ ਨੂੰ ਦਰਸਾਉਂਦਾ ਹੋਵੇ।",
