  "wealthDetail.insurance.maturityToday": "ਅੱਜ ਦੇ ਪੈਸੇ ਵਿੱਚ ਪਰਿਪੱਕਤਾ: ~{amount}",
  "wealthDetail.insurance.verdict.positive": "ਮੁਦਰਾਸਫੀਤੀ ਬਨਾਮ ਸੰਭਾਵਤ ਤੌਰ 'ਤੇ ਲਾਭਦਾਇਕ",
