  "wealthDetail.insurance.verdictDetail.positive": "ਪਰਿਪੱਕਤਾ (ਅੱਜ ਦੇ ਪੈਸੇ ਵਿੱਚ) ਇੱਕ ਸਧਾਰਨ ਮਹਿੰਗਾਈ ਵਿਵਸਥਾ ਦੇ ਬਾਅਦ ਕੁੱਲ ਪ੍ਰੀਮੀਅਮਾਂ ਤੋਂ ਉੱਪਰ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ।",
  "wealthDetail.insurance.verdictDetail.mild": "ਤੁਸੀਂ ਮਹਿੰਗਾਈ ਨੂੰ ਥੋੜ੍ਹਾ ਮਾਤ ਦੇ ਸਕਦੇ ਹੋ — ਤਨਖਾਹ ਅਤੇ ਸੁਰੱਖਿਆ ਦੀ ਜ਼ਰੂਰਤ ਦੇ ਪ੍ਰੀਮੀਅਮ ਹਿੱਸੇ ਦੀ ਜਾਂਚ ਕਰੋ।",
