  "wealthDetail.property.sellNegativeReturn": "ਅਸਲ ਰਿਟਰਨ ਮਹਿੰਗਾਈ ਤੋਂ ਬਾਅਦ ਨਕਾਰਾਤਮਕ ਹੈ. ਜੇਕਰ ਤਰਲਤਾ ਦੀ ਲੋੜ ਹੈ, ਤਾਂ ਇਹ ਵੇਚਣ ਦਾ ਵਾਜਬ ਸਮਾਂ ਹੈ - 5+ ਸਾਲਾਂ ਤੋਂ ਬਾਅਦ ਲੰਬੇ ਸਮੇਂ ਤੋਂ ਘੱਟ-ਕਾਰਗੁਜ਼ਾਰੀ।",
