  "wealthDetail.gold.sgbNote": "ਸਾਵਰੇਨ ਗੋਲਡ ਬਾਂਡ ਸੋਨੇ 'ਤੇ 2.5% ਸਲਾਨਾ ਵਿਆਜ ਅਤੇ ਕੀਮਤ ਵਧਾਉਂਦੇ ਹਨ, ਕੋਈ ਮੇਕਿੰਗ ਚਾਰਜ ਨਹੀਂ, ਅਤੇ 8 ਸਾਲਾਂ ਬਾਅਦ LTCG ਤੋਂ ਛੋਟ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ। ਨਵੀਂ ਸੋਨੇ ਦੀ ਖਰੀਦ ਲਈ, SGB ਜਾਂ ਗੋਲਡ ETF ਆਮ ਤੌਰ 'ਤੇ ਭੌਤਿਕ ਸਜਾਵਟੀ ਸੋਨੇ ਨਾਲੋਂ ਵਧੇਰੇ ਕੁਸ਼ਲ ਹੈ।",
  "wealthDetail.gold.holdWaitDetail": "ਤੁਸੀਂ {years} ਸਾਲਾਂ ਲਈ ਹੋਲਡ ਕੀਤਾ ਹੈ। ਹੁਣ ਵੇਚਣਾ ਤੁਹਾਡੀ ਸਲੈਬ ਦਰ ({slab}%) 'ਤੇ ਥੋੜ੍ਹੇ ਸਮੇਂ ਲਈ ਟੈਕਸ ਆਕਰਸ਼ਿਤ ਕਰਦਾ ਹੈ। {ltcgYears} ਸਾਲਾਂ ਤੱਕ ਹੋਲਡ ਕਰਨ ਨਾਲ ਟੈਕਸ ਵਿੱਚ ~₹{taxSaving} ਦੀ ਬਚਤ ਹੁੰਦੀ ਹੈ।",
  "wealthDetail.gold.holdGoodDetail": "ਸੋਨਾ {realReturn}% ਦੁਆਰਾ ਮਹਿੰਗਾਈ ਨੂੰ ਮਾਤ ਦੇ ਰਿਹਾ ਹੈ। ਹੋਲਡ ਕਰਨਾ ਜਾਰੀ ਰੱਖੋ - ਅਨਿਸ਼ਚਿਤਤਾ ਦੇ ਦੌਰਾਨ ਸੋਨਾ ਇੱਕ ਹੇਜ ਦੇ ਰੂਪ ਵਿੱਚ ਵਧੀਆ ਪ੍ਰਦਰਸ਼ਨ ਕਰਦਾ ਹੈ।",
  "wealthDetail.gold.holdReviewDetail": "ਅਸਲ ਵਾਪਸੀ ਨਕਾਰਾਤਮਕ ਹੈ ({realReturn}%)। ਸੋਨਾ ਮੁਦਰਾਸਫੀਤੀ ਦੇ ਨਾਲ ਤਾਲਮੇਲ ਨਹੀਂ ਬਣਾ ਰਿਹਾ ਹੈ - ਵਿਚਾਰ ਕਰੋ ਕਿ ਕੀ ਇਹ ਵੰਡ ਤੁਹਾਡੇ ਟੀਚਿਆਂ ਲਈ ਸਹੀ ਹੈ।",
  "wealthDetail.gold.holdModerateDetail": "ਸੋਨਾ ਮਹਿੰਗਾਈ ਬਨਾਮ ਮੁੱਲ ਨੂੰ ਕਾਇਮ ਰੱਖ ਰਿਹਾ ਹੈ। ਹੇਜ ਦੇ ਤੌਰ 'ਤੇ ਚੰਗਾ — ਆਮ ਤੌਰ 'ਤੇ ਪੋਰਟਫੋਲੀਓ ਦਾ 5-10%।",
