  "wealthDetail.fd.debtMfTitle": "ਰਿਣ ਮਿਉਚੁਅਲ ਫੰਡ ਦੀ ਤੁਲਨਾ",
  "wealthDetail.fd.debtMfNote": "ਕਰਜ਼ਾ ਮਿਉਚੁਅਲ ਫੰਡ (ਜਿਵੇਂ ਥੋੜ੍ਹੇ ਸਮੇਂ ਦੀ ਮਿਆਦ ਜਾਂ ਕਾਰਪੋਰੇਟ ਬਾਂਡ ਫੰਡ) ਸਮਾਨ ਰਿਟਰਨ ਪੇਸ਼ ਕਰਦੇ ਹਨ ਪਰ ਰਿਡੈਂਪਸ਼ਨ 'ਤੇ ਤੁਹਾਡੀ ਸਲੈਬ ਦਰ 'ਤੇ ਟੈਕਸ ਲਗਾਇਆ ਜਾਂਦਾ ਹੈ - FD ਵਰਗਾ ਕੋਈ ਸਾਲਾਨਾ TDS ਨਹੀਂ। ਉਹ ਬਿਹਤਰ ਤਰਲਤਾ ਦੀ ਪੇਸ਼ਕਸ਼ ਵੀ ਕਰਦੇ ਹਨ (T+1 ਰੀਡੈਂਪਸ਼ਨ ਬਨਾਮ FD ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਕਢਵਾਉਣ ਦੀ ਸਜ਼ਾ)।",
