  "wealthDetail.fd.niftyHistorical": "Nifty 50 (historical)",
  "wealthDetail.fd.holdGoodDetail": "FD ਪੂੰਜੀ ਸੁਰੱਖਿਆ ਅਤੇ ਅਨੁਮਾਨਿਤ ਰਿਟਰਨ ਪ੍ਰਦਾਨ ਕਰਦਾ ਹੈ। ਐਮਰਜੈਂਸੀ ਫੰਡ ਜਾਂ ਛੋਟੀ ਮਿਆਦ ਦੇ ਟੀਚਿਆਂ (3 ਸਾਲ ਤੋਂ ਘੱਟ) ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ।",
  "wealthDetail.fd.holdReviewDetail": "ਟੈਕਸ ਅਤੇ ਮਹਿੰਗਾਈ ਤੋਂ ਬਾਅਦ, ਇਹ FD ਪ੍ਰਤੀ ਸਾਲ {realReturn}% ਅਸਲ ਖਰੀਦ ਸ਼ਕਤੀ ਗੁਆ ਰਹੀ ਹੈ। ਜਦੋਂ ਇਹ FD ਪਰਿਪੱਕ ਹੋ ਜਾਂਦੀ ਹੈ ਤਾਂ ਕਰਜ਼ੇ ਦੇ ਮਿਉਚੁਅਲ ਫੰਡਾਂ (ਵਧੇਰੇ ਟੈਕਸ-ਕੁਸ਼ਲ) ਜਾਂ I-ਬਾਂਡਾਂ ਲਈ ਅੰਸ਼ਕ ਮੁੜ-ਸਥਾਨ 'ਤੇ ਵਿਚਾਰ ਕਰੋ।",
  "wealthDetail.fd.holdMaturitySoonDetail": "ਇਹ FD {months} ਮਹੀਨਿਆਂ ਵਿੱਚ ਪੱਕ ਜਾਂਦੀ ਹੈ। ਹੁਣੇ ਨਵਿਆਉਣ ਦੀ ਰਣਨੀਤੀ ਦਾ ਫੈਸਲਾ ਕਰੋ — ਸਵੈ-ਨਵੀਨੀਕਰਨ ਤੁਹਾਨੂੰ ਘੱਟ ਦਰ ਵਿੱਚ ਬੰਦ ਕਰ ਸਕਦਾ ਹੈ।",
